create temporary view  traffic_data_raw_${grass_region_without_quote}
as
select  if(operation = 'order', 'order', 'others') as operation
        ,local_hour
        ,is_item_card
        ,shop_id
        ,item_id
        ,model_id
        ,user_id
        ,if(is_ads, 'true', 'false') as is_ads
        ,if(source1_is_ads, 'true', 'false') as source1_is_ads
        ,if(source2_is_ads, 'true', 'false') as source2_is_ads
        ,feature_detail
        ,source1_feature_detail
        ,source2_feature_detail
        ,feature_group
        ,reporting_business_line
        ,reporting_module
        ,reporting_object
        ,source1_feature_group
        ,source1_reporting_business_line
        ,source1_reporting_module
        ,source1_reporting_object
        ,source2_feature_group
        ,source2_reporting_business_line
        ,source2_reporting_module
        ,source2_reporting_object
        ,sum(imp_cnt) as imp_cnt
        ,sum(click_cnt) as click_cnt
        ,sum(order_cnt) as order_cnt
        ,sum(gmv) as gmv
        ,sum(gmv_local) as gmv_local
        ,sum(pc2_gmv) as pc2_gmv
from    srdi_mart.dwm_sr_data_warehouse_tc_ab_all_cards
where   grass_region IN (${grass_region})
  and   local_date = ${local_date}
  and   operation in ('order', 'omni_impression', 'omni_click')
group by if(operation = 'order', 'order', 'others'), local_hour, is_item_card, shop_id, item_id, model_id, user_id, is_ads, source1_is_ads, source2_is_ads, feature_detail, source1_feature_detail, source2_feature_detail, feature_group, reporting_business_line, reporting_module, reporting_object, source1_feature_group, source1_reporting_business_line, source1_reporting_module, source1_reporting_object, source2_feature_group, source2_reporting_business_line, source2_reporting_module, source2_reporting_object
;

--sql_divide_splitter--
cache   table every_scene_data_raw_step1_${grass_region_without_quote} options ('storageLevel' 'DISK_ONLY') as
select  operation
        ,is_item_card
        ,user_id
        ,is_ads
        ,source1_is_ads
        ,source2_is_ads
        ,shop_id
        ,item_id
        ,model_id
        ,case   when (reporting_module = 'User Scenario' and reporting_object = 'post purchase' and feature_detail like 'osp_ymal%') then 'Post Purchase OSP'
                when (reporting_module = 'User Scenario' and reporting_object = 'post purchase' and feature_detail like 'mpp_ymal%') then 'Post Purchase MPP'
                when feature_group in ('Shop Product Tab') then 'Shop Product Tab'
                when feature_group in ('Shop Recommended For You') then 'Shop Recommended For You'
                when feature_group in ('Shop Main Browsing') then 'Shop Main Browsing'
                when feature_group in ('From the Same Shop') then 'From the Same Shop'
                else ''	-- 任何非归因数据都需要有场景
         end as mapping_general
        ,case   when (source1_reporting_module = 'User Scenario' and source1_reporting_object = 'post purchase' and source1_feature_detail like 'osp_ymal%') then 'Post Purchase OSP'
                when (source1_reporting_module = 'User Scenario' and source1_reporting_object = 'post purchase' and source1_feature_detail like 'mpp_ymal%') then 'Post Purchase MPP'
                else ''
         end as source1_mapping_general
        ,case   when (source2_reporting_module = 'User Scenario' and source2_reporting_object = 'post purchase' and source2_feature_detail like 'osp_ymal%') then 'Post Purchase OSP'
                when (source2_reporting_module = 'User Scenario' and source2_reporting_object = 'post purchase' and source2_feature_detail like 'mpp_ymal%') then 'Post Purchase MPP'
                else ''
         end as source2_mapping_general
        ,imp_cnt
        ,click_cnt
        ,order_cnt
        ,gmv
        ,gmv_local
        ,pc2_gmv
        ,local_hour
from    traffic_data_raw_${grass_region_without_quote}
where   (
        (
                (
                        reporting_module = 'User Scenario'
                    and reporting_object = 'post purchase'
                    and feature_detail like 'osp_ymal%'
                )
            or  (
                        reporting_module = 'User Scenario'
                    and reporting_object = 'post purchase'
                    and feature_detail like 'mpp_ymal%'
                )
            or  feature_group in ('Shop Product Tab')
            or  feature_group in ('Shop Recommended For You')
            or  feature_group in ('Shop Main Browsing')
            or  feature_group in ('From the Same Shop')
        )
    or  (
                (
                        source1_reporting_module = 'User Scenario'
                    and source1_reporting_object = 'post purchase'
                    and source1_feature_detail like 'osp_ymal%'
                )
            or  (
                        source1_reporting_module = 'User Scenario'
                    and source1_reporting_object = 'post purchase'
                    and source1_feature_detail like 'mpp_ymal%'
                )
        )
    or  (
                (
                        source2_reporting_module = 'User Scenario'
                    and source2_reporting_object = 'post purchase'
                    and source2_feature_detail like 'osp_ymal%'
                )
            or  (
                        source2_reporting_module = 'User Scenario'
                    and source2_reporting_object = 'post purchase'
                    and source2_feature_detail like 'mpp_ymal%'
                )
        )
)
;

