        ,user_id
        ,source1_is_ads as is_ads
        ,source1_mapping_general as mapping_general
        ,shop_id
        ,item_id
        ,model_id
        ,imp_cnt
        ,click_cnt
        ,order_cnt
        ,gmv
        ,gmv_local
        ,pc2_gmv
