where   source2_mapping_general in ('Post Purchase OSP', 'Post Purchase MPP', 'Shop Product Tab', 'Shop Recommended For You', 'Shop Main Browsing', 'From the Same Shop')
  and   operation = 'order'
  and   source2_mapping_general != mapping_general
  and   source2_mapping_general != source1_mapping_general	--to guarantee order not copy double
;

