create temporary view  traffic_data_item_${grass_region_without_quote} as
select  user_id
        ,item_id
        ,is_ads
        ,mapping_general
        ,sum(imp_cnt) as imp_cnt
        ,sum(click_cnt) as click_cnt
        ,sum(order_cnt) as order_cnt
        ,sum(gmv) as gmv
        ,sum(gmv_local) as gmv_local
        ,sum(pc2_gmv) as pc2_gmv
from    (
    select  is_item_card
            ,user_id
            ,item_id
            ,is_ads
            ,mapping_general
            ,imp_cnt
            ,click_cnt
            ,order_cnt
            ,gmv
            ,gmv_local
            ,pc2_gmv
    from    srdi_mart.dws_sr_data_warehouse_tc_pb_basic_aggr_1d
    where   grass_region = ${grass_region}
      and   local_date = ${local_date}
      and   mapping_general in ('Post Purchase', 'Daily Discover', 'Search', 'You May Also Like', 'Shop', 'S&R__ALL__', '__ALL__')
    union all
    select  is_item_card
            ,user_id
            ,item_id
            ,is_ads
            ,'S&R__MAIN__' AS mapping_general
            ,imp_cnt
            ,click_cnt
            ,order_cnt
            ,gmv
            ,gmv_local
            ,pc2_gmv
    from    srdi_mart.dws_sr_data_warehouse_tc_pb_basic_aggr_1d
    where   grass_region = ${grass_region}
      and   local_date = ${local_date}
      and   mapping_general in ('Daily Discover', 'Search', 'You May Also Like')
    union all
    select  is_item_card
            ,user_id
            ,item_id
            ,is_ads
            ,mapping_general
            ,imp_cnt
            ,click_cnt
            ,order_cnt
            ,gmv
            ,gmv_local
            ,pc2_gmv
    from    every_scene_data_raw_step2_${grass_region_without_quote}
)
group by 1, 2, 3, 4
;

-- 995口径计算
--sql_divide_splitter--
create temporary view     basic_scene_data_${grass_region_without_quote}
as
select  T1.*
        ,T2.exp_group_id
from    (
    select  T1.*
            ,case   when DATEDIFF(${local_date}, DATE(T2.item_create_datetime)) BETWEEN 0 AND 10 THEN '10d'
                    when DATEDIFF(${local_date}, DATE(T2.item_create_datetime)) BETWEEN 11 AND 20 THEN '20d'
                    when DATEDIFF(${local_date}, DATE(T2.item_create_datetime)) BETWEEN 21 AND 30 THEN '30d'
                    when DATEDIFF(${local_date}, DATE(T2.item_create_datetime)) BETWEEN 31 AND 90 THEN '90d'
                    ELSE 'others'
             end as create_date_type
    from    (
        select  *
        from    traffic_data_item_${grass_region_without_quote}
    ) T1
    left join (
        select  item_id
                ,max(item_create_datetime) as item_create_datetime
        from    srdi_mart.dim_sr_data_warehouse_item
        where   grass_region = ${grass_region}
          and   local_date = ${local_date}
          group by 1
    ) T2
    on      T1.item_id = T2.item_id
) as T1
inner join user_exp_${grass_region_without_quote} as T2
on      T1.user_id = T2.user_id
;

--sql_divide_splitter--
create temporary view scene_995_threshold_${grass_region_without_quote}
as
select  *
from    srdi_mart.dws_sr_data_warehouse_tc_scene_995_threshold_1d
where   grass_region IN (${grass_region})
  and   local_date = ${local_date}
;

--sql_divide_splitter--
create temporary view  scene_data_${grass_region_without_quote}  as
select  mapping_general
        ,is_ads
        ,exp_group_id
        ,create_date_type
        ,sum(item_imp_pv) as item_imp_pv
        ,sum(item_imp_uv) as item_imp_uv
        ,sum(item_imp_uv_995) as item_imp_uv_995
        ,sum(item_click_pv) as item_click_pv
        ,sum(order_cnt) as order_cnt
        ,sum(order_uv) as order_uv
        ,sum(gmv) as gmv
        ,sum(gmv_995) as gmv_995
        ,sum(pc2_gmv) as pc2_gmv
        ,sum(pc2_gmv_995) as pc2_gmv_995
        ,sum(exposed_item_cnt) as exposed_item_cnt
        ,sum(clicked_item_cnt) as clicked_item_cnt
        ,sum(ordered_item_cnt) as ordered_item_cnt
from    (
    select  mapping_general
            ,is_ads
            ,exp_group_id
            ,create_date_type
            ,sum(item_imp_pv) as item_imp_pv
            ,sum(if(item_imp_pv > 0, 1, null)) as item_imp_uv
            ,sum(case when gpo <= gpo_pct and item_imp_pv > 0  and user_id > 0 then 1 else NULL end) as item_imp_uv_995
            ,sum(item_click_pv) as item_click_pv
            ,sum(order_cnt) as order_cnt
            ,sum(if(order_cnt > 0  and user_id > 0, 1, null)) as order_uv
            ,sum(gmv) as gmv
            ,sum(case when gpo <= gpo_pct then gmv else 0 end) as gmv_995
            ,sum(pc2_gmv) as pc2_gmv
            ,sum(case when gpo <= gpo_pct then pc2_gmv else 0 end) as pc2_gmv_995
            ,0 as exposed_item_cnt
            ,0 as clicked_item_cnt
            ,0 as ordered_item_cnt
    from    (
        select  a.*
                ,b.gpo_pct
        from    (
            select  mapping_general
                    ,if(grouping(is_ads) = 1, '__ALL__', is_ads) as is_ads
                    ,'__ALL__' as is_item_card	-- for is_item_card=false and order log ,is not right
                    ,if(grouping(create_date_type) = 1, '__ALL__', create_date_type) as create_date_type
                    ,user_id
                    ,exp_group_id
                    ,sum(imp_cnt) as item_imp_pv
                    -- item_imp_uv
                    --item_imp_uv_995
                    ,sum(click_cnt) as item_click_pv
                    ,sum(order_cnt) as order_cnt
                    --order_uv
                    ,sum(gmv) as gmv
                    ,sum(gmv_local) as gmv_local
                    --gmv_995
                    ,sum(pc2_gmv) as pc2_gmv
                    -- pc2_gmv_995
                    ,COALESCE(SUM(gmv) / NULLIF(SUM(order_cnt), 0), 0) AS gpo
            from    basic_scene_data_${grass_region_without_quote}
            group by GROUPING SETS ((mapping_general, exp_group_id, user_id, is_ads, create_date_type), (mapping_general, exp_group_id, user_id, is_ads), (mapping_general, exp_group_id, user_id, create_date_type), (mapping_general, exp_group_id, user_id))
        ) as a
        left join scene_995_threshold_${grass_region_without_quote} b
        on      a.mapping_general = b.mapping_general
          and   a.is_ads = b.is_ads
          and   a.is_item_card = b.is_item_card
    )
    group by 1, 2, 3, 4
    union all
    select  mapping_general
            ,is_ads
            ,exp_group_id
            ,create_date_type
            ,0 as item_imp_pv
            ,0 as item_imp_uv
            ,0 as item_imp_uv_995
            ,0 as item_click_pv
            ,0 as order_cnt
            ,0 as order_uv
            ,0 as gmv
            ,0 as gmv_995
            ,0 as pc2_gmv
            ,0 as pc2_gmv_995
            ,sum(if(item_imp_pv > 0 and item_id > 0, 1, NULL)) as exposed_item_cnt
            ,sum(if(item_click_pv > 0 and item_id > 0 , 1, NULL)) as clicked_item_cnt
            ,sum(if(order_cnt > 0 and item_id > 0, 1, NULL)) as ordered_item_cnt
    from    (
        select  mapping_general
                ,if(grouping(is_ads) = 1, '__ALL__', is_ads) as is_ads
                ,if(grouping(create_date_type) = 1, '__ALL__', create_date_type) as create_date_type
                ,exp_group_id
                ,item_id
                ,sum(imp_cnt) as item_imp_pv
                ,sum(click_cnt) as item_click_pv
                ,sum(order_cnt) as order_cnt
        from    basic_scene_data_${grass_region_without_quote}
        group by GROUPING SETS ((mapping_general, exp_group_id, item_id, is_ads, create_date_type), (mapping_general, exp_group_id, item_id, is_ads), (mapping_general, exp_group_id, item_id, create_date_type), (mapping_general, exp_group_id, item_id))
    )
    group by 1, 2, 3, 4
)
group by 1, 2, 3, 4
;

--sql_divide_splitter--
create temporary view    ads_raw_step1_${grass_region_without_quote}
as
select  item_id
        ,user_id
        ,is_roi2
        ,ads_revenue_local
        ,ads_revenue_usd
        ,ads_order_gmv_usd
        ,ads_advv_broad_usd
        ,case   when T2.traffic_type = 'Livestream' then 'Live Streaming'
                else coalesce(T2.traffic_type, 'Other')
         end as common_feature
from    (
    select  item_id
            ,user_id
            ,if (pricing_type in (11, 15), 1, 0) as is_roi2
            ,expenditure_amt_local as ads_revenue_local
            ,expenditure_amt_usd as ads_revenue_usd
            ,ads_order_gmv_usd
            ,broad_gmv_amt_local / exchange_rate * coalesce(target_cir, 0) ads_advv_broad_usd
            ,entrance
    from    mp_paidads.dwd_advertise_performance_di__reg_s0_live a
    left join mp_order.dim_exchange_rate__reg_s0_live b
    on      a.grass_date = b.grass_date
      and   a.grass_region = b.grass_region
    where   a.grass_region in (${grass_region})
      and   a.grass_date = ${local_date}
      and   a.tz_type = 'local'
      and   ads_id > 0
) as T1
left join (
    select  entrance
            ,max(traffic_type) as traffic_type
    from    mp_paidads.dim_entry_point_mapping_v2
    group by 1
) as T2
on      T1.entrance = T2.entrance
;

--sql_divide_splitter--
create temporary view    ads_raw_step2_${grass_region_without_quote}
as
select  item_id
        ,user_id
        ,common_feature
        ,sum(ads_revenue_local) as ads_revenue_local
        ,sum(ads_revenue_usd) as ads_revenue_usd
        ,sum(if (is_roi2 = 1, ads_revenue_local, 0)) as ads_revenue_local_roi2
        ,sum(if (is_roi2 = 1, ads_revenue_usd, 0)) as ads_revenue_usd_roi2
        ,sum(ads_order_gmv_usd) as ads_order_gmv_usd
        ,sum(ads_advv_broad_usd) as ads_advv_broad_usd
from    ads_raw_step1_${grass_region_without_quote}
group by item_id, user_id, common_feature
;

--sql_divide_splitter--
create temporary view    ads_raw_step3_${grass_region_without_quote}
as
select  T1.item_id
        ,user_id
        ,common_feature
        ,ads_revenue_local
        ,ads_revenue_usd
        ,ads_revenue_local_roi2
        ,ads_revenue_usd_roi2
        ,ads_order_gmv_usd
        ,ads_advv_broad_usd
        ,case   when DATEDIFF(${local_date}, DATE(T2.item_create_datetime)) BETWEEN 0 AND 10 THEN '10d'
                when DATEDIFF(${local_date}, DATE(T2.item_create_datetime)) BETWEEN 11 AND 20 THEN '20d'
                when DATEDIFF(${local_date}, DATE(T2.item_create_datetime)) BETWEEN 21 AND 30 THEN '30d'
                when DATEDIFF(${local_date}, DATE(T2.item_create_datetime)) BETWEEN 31 AND 90 THEN '90d'
                ELSE 'others'
         end as create_date_type
from    ads_raw_step2_${grass_region_without_quote} as T1
left join (
    select  item_id
            ,max(item_create_datetime) as item_create_datetime
    from    srdi_mart.dim_sr_data_warehouse_item
    where   grass_region = ${grass_region}
      and   local_date = ${local_date}
      group by 1
) T2
on      T1.item_id = T2.item_id
;

--sql_divide_splitter--
create temporary view    ads_raw_step4_${grass_region_without_quote}  as
select  user_id
        ,common_feature
        ,create_date_type
        ,sum(ads_revenue_local) as ads_revenue_local
        ,sum(ads_revenue_usd) as ads_revenue_usd
        ,sum(ads_revenue_local_roi2) as ads_revenue_local_roi2
        ,sum(ads_revenue_usd_roi2) as ads_revenue_usd_roi2
        ,sum(ads_order_gmv_usd) as ads_order_gmv_usd
        ,sum(ads_advv_broad_usd) as ads_advv_broad_usd
from    ads_raw_step3_${grass_region_without_quote}
where   common_feature in ('Search', 'You May Also Like', 'Daily Discover', 'Post Purchase', 'Shop')
group by user_id, common_feature,create_date_type
union all
select  user_id
        ,'S&R__ALL__' as common_feature
        ,create_date_type
        ,sum(ads_revenue_local) as ads_revenue_local
        ,sum(ads_revenue_usd) as ads_revenue_usd
        ,sum(ads_revenue_local_roi2) as ads_revenue_local_roi2
        ,sum(ads_revenue_usd_roi2) as ads_revenue_usd_roi2
        ,sum(ads_order_gmv_usd) as ads_order_gmv_usd
        ,sum(ads_advv_broad_usd) as ads_advv_broad_usd
from    ads_raw_step3_${grass_region_without_quote}
where   common_feature in ('Search', 'You May Also Like', 'Daily Discover', 'Post Purchase')
group by user_id, common_feature,create_date_type
union all
select  user_id
        ,'__ALL__' as common_feature
        ,create_date_type
        ,sum(ads_revenue_local) as ads_revenue_local
        ,sum(ads_revenue_usd) as ads_revenue_usd
        ,sum(ads_revenue_local_roi2) as ads_revenue_local_roi2
        ,sum(ads_revenue_usd_roi2) as ads_revenue_usd_roi2
        ,sum(ads_order_gmv_usd) as ads_order_gmv_usd
        ,sum(ads_advv_broad_usd) as ads_advv_broad_usd
from    ads_raw_step3_${grass_region_without_quote}
group by user_id,create_date_type
union all
select  user_id
        ,'S&R__MAIN__' as common_feature
        ,create_date_type
        ,sum(ads_revenue_local) as ads_revenue_local
        ,sum(ads_revenue_usd) as ads_revenue_usd
        ,sum(ads_revenue_local_roi2) as ads_revenue_local_roi2
        ,sum(ads_revenue_usd_roi2) as ads_revenue_usd_roi2
        ,sum(ads_order_gmv_usd) as ads_order_gmv_usd
        ,sum(ads_advv_broad_usd) as ads_advv_broad_usd
from    ads_raw_step3_${grass_region_without_quote}
where   common_feature in ('Search', 'You May Also Like', 'Daily Discover')
group by user_id, common_feature,create_date_type
;

--sql_divide_splitter--
create temporary view    ads_${grass_region_without_quote} as
select  a.user_id
        ,b.exp_group_id
        ,common_feature
        ,create_date_type
        ,ads_revenue_usd
        ,ads_revenue_usd_roi2
from    ads_raw_step4_${grass_region_without_quote} a
inner join user_exp_${grass_region_without_quote} b
on      a.user_id = b.user_id
;

--sql_divide_splitter--
create temporary view    exp_ads_${grass_region_without_quote}  as
select  exp_group_id
        ,common_feature
        ,if(grouping(create_date_type) =1 , '__ALL__', create_date_type) as create_date_type
        ,sum(ads_revenue_usd) as scene_ads_revenue_usd
        ,sum(ads_revenue_usd_roi2) as scene_ads_revenue_usd_roi2
from    ads_${grass_region_without_quote}
group by GROUPING SETS ((common_feature, exp_group_id, create_date_type),
                        (common_feature, exp_group_id))
;

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_tc_ni_new_item_createdate_scene_exp_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})
select
        T1.is_ads
        ,T1.mapping_general
        ,layer_id
        ,experiment_id
        ,T1.exp_group_id
        ,exp_group_type
        ,T1.create_date_type

        ,item_imp_pv
        ,item_imp_uv
        ,item_imp_uv_995
        ,item_click_pv
        ,order_cnt
        ,order_uv
        ,gmv
        ,gmv_995
        ,pc2_gmv
        ,pc2_gmv_995

        ,scene_ads_revenue_usd
        ,scene_ads_revenue_usd_roi2

        ,exposed_item_cnt
        ,clicked_item_cnt
        ,ordered_item_cnt
from    scene_data_${grass_region_without_quote} as T1
left join exp_traffic_info_${grass_region_without_quote} as T2
on      T1.exp_group_id = T2.exp_group_id
left join exp_ads_${grass_region_without_quote} as T3
on      T1.mapping_general = T3.common_feature
  and   T1.exp_group_id = T3.exp_group_id
  and   T1.create_date_type = T3.create_date_type
  and   T1.is_ads = '__ALL__'
;
